from typing import List

class Solution:
    def findDiagonalOrder(self, mat: List[List[int]]) -> List[int]:
        if not mat or not mat[0]:
            return []

        m, n = len(mat), len(mat[0])
        result = []
        r, c = 0, 0
        direction = 1  # 1 for up-right, -1 for down-left

        for _ in range(m * n):
            result.append(mat[r][c])
            if direction == 1:
                if c == n - 1:
                    r += 1
                    direction = -1
                elif r == 0:
                    c += 1
                    direction = -1
                else:
                    r -= 1
                    c += 1
            else:
                if r == m - 1:
                    c += 1
                    direction = 1
                elif c == 0:
                    r += 1
                    direction = 1
                else:
                    r += 1
                    c -= 1

        return result
```

This solution handles the diagonal traversal of the matrix by keeping track of the current row (`r`) and column (`c`) and the direction of traversal (`direction`). The direction alternates between up-right (`1`) and down-left (`-1`). The traversal continues until all elements are visited, and the result is collected in the `result` list.

