    def findLength(self, nums1: List[int], nums2: List[int]) -> int:
        # Create a 2D DP array to store lengths of longest common suffixes
        # Initialize all values to 0
        dp = [[0] * (len(nums2) + 1) for _ in range(len(nums1) + 1)]

