                        stack.append(num)
                    elif sign == '-':
                        stack.append(-num)
                    elif sign == '*':
                        stack.append(stack.pop() * num)
                    elif sign == '/':
                        stack.append(int(stack.pop() / num))  # Truncate toward zero

                    sign = char
                    num = 0

                if char == ')':
                    break

            return sum(stack)

        # Convert string to list for easier manipulation
        return helper(list(s))
