class Solution:
    def findBestValue(self, arr: List[int], target: int) -> int:
        def array_sum_with_value(val):
            return sum(min(a, val) for a in arr)

        left, right = 0, max(arr)
        best_value = left
        min_diff = float('inf')

        while left <= right:
