    def minimumDistance(self, word: str) -> int:
        def dist(c1, c2):
            if c1 is None:
                return 0
            x1, y1 = divmod(ord(c1) - ord('A'), 6)
            x2, y2 = divmod(ord(c2) - ord('A'), 6)
            return abs(x1 - x2) + abs(y1 - y2)

