from typing import List
from collections import defaultdict

class Solution:
    def diagonalSort(self, mat: List[List[int]]) -> List[List[int]]:
        # Dictionary to hold the diagonals
        diagonals = defaultdict(list)

        # Collect all elements of the same diagonal
        for i in range(len(mat)):
            for j in range(len(mat[0])):
                diagonals[i - j].append(mat[i][j])

        # Sort each diagonal
        for key in diagonals:
            diagonals[key].sort(reverse=True)

        # Place the sorted elements back into the matrix
        for i in range(len(mat)):
            for j in range(len(mat[0])):
                mat[i][j] = diagonals[i - j].pop()

        return mat
```

This solution works by first collecting all the elements of each diagonal into a dictionary where the key is the difference between the row and column indices (`i - j`). Each diagonal is then sorted in reverse order, and the elements are placed back into the matrix in sorted order. The use of `defaultdict(list)` makes it easy to append elements to the correct diagonal list without checking if the key exists.

