from typing import List

class Solution:
    def countNegatives(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        count = 0
        row, col = m - 1, 0

        while row >= 0 and col < n:
            if grid[row][col] < 0:
                count += (n - col)
                row -= 1
            else:
                col += 1

        return count
```

This solution leverages the fact that the grid is sorted in non-increasing order both row-wise and column-wise. It starts from the bottom-left corner of the grid and moves either right or up based on the value of the current cell, achieving an O(m + n) time complexity.

