class Solution:
    def countSubstrings(self, s: str, t: str) -> int:
        def count_differing_by_one(start_s, start_t):
            count = 0
            diff_count = 0
            for i in range(min(len(s) - start_s, len(t) - start_t)):
                if s[start_s + i] != t[start_t + i]:
                    diff_count += 1
                if diff_count > 1:
