from typing import List
from math import inf

class Solution:
    def countPaths(self, n: int, roads: List[List[int]]) -> int:
        g = [[inf] * n for _ in range(n)]
        for u, v, t in roads:
            g[u][v] = g[v][u] = t
        g[0][0] = 0
        dist = [inf] * n
        dist[0] = 0
        f = [0] * n
        f[0] = 1
        vis = [False] * n
        for _ in range(n):
            t = -1
            for j in range(n):
                if not vis[j] and (t == -1 or dist[j] < dist[t]):
                    t = j
            vis[t] = True
            for j in range(n):
                if j == t:
                    continue
                ne = dist[t] + g[t][j]
                if dist[j] > ne:
                    dist[j] = ne
                    f[j] = f[t]
                elif dist[j] == ne:
                    f[j] += f[t]
        mod = 10**9 + 7
        return f[-1] % mod
```

This solution uses a modified Dijkstra's algorithm to find the shortest path from intersection 0 to intersection n-1 and counts the number of ways to achieve this shortest path. The graph is represented as an adjacency matrix `g`, and the shortest distances from the starting node to each node are stored in `dist`. The number of ways to reach each node with the shortest path is stored in `f`. The algorithm iteratively selects the unvisited node with the smallest known distance, updates the distances and ways to reach its neighbors, and marks the node as visited. The result is the number of ways to reach the destination node modulo \(10^9 + 7\).

