        if digit1 > digit2:
            digit1, digit2 = digit2, digit1

        # BFS approach to generate numbers with only digit1 and digit2
        from collections import deque

        queue = deque()
        if digit1 != 0:
            queue.append(digit1)
        if digit2 != 0:
            queue.append(digit2)

        max_32bit_int = 2**31 - 1

        while queue:
            current = queue.popleft()

            if current > max_32bit_int:
