class Solution:
    def minDeletion(self, nums: List[int]) -> int:
        deletions = 0
        i = 0

        # Iterate through the array with the adjusted index
        while i < len(nums) - 1:
            # If the current index (after deletions) is even and nums[i] == nums[i + 1]
            if (i - deletions) % 2 == 0 and nums[i] == nums[i + 1]:
