from typing import List

class Solution:
    def kthPalindrome(self, queries: List[int], intLength: int) -> List[int]:
        def generate_palindrome(half, is_odd):
            half_str = str(half)
            if is_odd:
                return int(half_str + half_str[-2::-1])
            else:
                return int(half_str + half_str[::-1])

        half_length = (intLength + 1) // 2
        start = 10**(half_length - 1)
        end = 10**half_length - 1
        is_odd = intLength % 2 == 1

        result = []
        for query in queries:
            half_number = start + query - 1
            if half_number > end:
                result.append(-1)
            else:
                result.append(generate_palindrome(half_number, is_odd))

        return result
```

This solution calculates the `k`th palindrome of a given length by generating the first half of the palindrome and mirroring it to form the full palindrome. It handles both odd and even length palindromes and checks if the query index is within the range of possible palindromes for the given length. If a query is out of range, it appends `-1` to the result.

