from typing import List

class Solution:
    def totalSteps(self, nums: List[int]) -> int:
        n = len(nums)
        stack = []
        days = [0] * n

        # Traverse the array from right to left
        for i in range(n - 1, -1, -1):
            while stack and nums[i] > nums[stack[-1]]:
                days[i] = max(days[i] + 1, days[stack.pop()])
            stack.append(i)

        return max(days)
```

