class Solution:
    def reverseOddLevels(self, root: Optional[TreeNode]) -> Optional[TreeNode]:
        if not root:
            return root

        # Queue for level order traversal
        queue = deque([root])
        level = 0

        while queue:
            level_size = len(queue)
            nodes_to_reverse = []

            for _ in range(level_size):
                node = queue.popleft()

                if level % 2 == 1:
