            if level % 2 == 1:
                for i in range(len(nodes_to_reverse) // 2):
                    nodes_to_reverse[i].val, nodes_to_reverse[~i].val = nodes_to_reverse[~i].val, nodes_to_reverse[i].val

            level += 1

        return root
