from collections import defaultdict

class Solution:
    def componentValue(self, nums: List[int], edges: List[List[int]]) -> int:
        def dfs(node, parent, target):
            total = nums[node]
            for neighbor in g[node]:
                if neighbor == parent:
                    continue
                subtree_sum, is_valid = dfs(neighbor, node, target)
                if not is_valid:
                    return (0, False)
                total += subtree_sum
            if total > target:
                return (0, False)
            if total == target:
                return (0, True)
            return (total, True)

        n = len(nums)
        total_sum = sum(nums)

        # Create adjacency list for the tree
        g = defaultdict(list)
        for u, v in edges:
            g[u].append(v)
            g[v].append(u)

        # Check all divisors of total_sum as potential component values
        max_deletions = 0
        for components in range(2, n + 1):
            if total_sum % components == 0:
                target = total_sum // components
                _, is_possible = dfs(0, -1, target)
                if is_possible:
                    max_deletions = components - 1

        return max_deletions
```

