class Solution:
    def longestAlternatingSubarray(self, nums: List[int], threshold: int) -> int:
        max_length = 0
        current_length = 0

        for i in range(len(nums)):
            if nums[i] > threshold:
                current_length = 0
            elif current_length == 0:
                if nums[i] % 2 == 0:
