                if mask >> cur & 1 == 0:
                    if abs(pre - nums[cur]) + dfs(mask | (1 << cur), cur) == res:
                        g(mask | (1 << cur), cur)
                        break

        n = len(nums)
        ans = []
        g(1, 0)
        return ans
